// sheet-metal-flat: a plate with a 10 mm flange bent 60° up from its y = 30 edge, a 4 x 40 slot across the bend cut in its flat
export function c007(context is Context, id is Id)
{
    smFlanged(context, id + "p", vector(20, 30, 2) * millimeter, 10 * millimeter, 60 * degree, false);
    const flatPlane = evPlane(context, { "face" : qCorrespondingInFlat(qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "p" + "sm1", EntityType.BODY), BodyType.SOLID), EntityType.FACE), vector(20, 15, 2) * millimeter)) });
    const f = newSketch(context, id + "f", { "sketchPlane" : qCorrespondingInFlat(qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "p" + "sm1", EntityType.BODY), BodyType.SOLID), EntityType.FACE), vector(20, 15, 2) * millimeter)) });
    skRectangle(f, "r", { "firstCorner" : vector(-2, -5) * millimeter, "secondCorner" : vector(2, 35) * millimeter });
    skSolve(f);
    extrude(context, id + "flat1", { "bodyType" : ExtendedToolBodyType.SOLID, "entities" : qSketchRegion(id + "f"), "domain" : OperationDomain.FLAT, "flatOperationType" : FlatOperationType.REMOVE, "endBound" : BoundingType.BLIND, "depth" : 2 * millimeter });
    return { "flatPlane" : { "origin" : round6(flatPlane.origin), "normal" : flatPlane.normal, "x" : flatPlane.x }, "faces" : faceProbe(context, qBodyType(qCreatedBy(id + "p" + "sm1", EntityType.BODY), BodyType.SOLID)) };
}

